[
 {
  "type": "text",
  "text": "{\"query\":\"COC(=O)[C@@H](N)CO.Cl.O=C(O)Cc1ccc(-c2noc(C(F)(F)F)n2)cc1>>COC(=O)[C@H](CO)NC(=O)Cc1ccc(-c2noc(C(F)(F)F)n2)cc1\",\"results\":[{\"reactants\":\"CC(C)(C)OC(=O)CN.O=C(O)Cc1ccc([N+](=O)[O-])cc1\",\"products\":\"CC(C)(C)OC(=O)CNC(=O)Cc1ccc([N+](=O)[O-])cc1\",\"solvents\":\"ClCCl\",\"reagents\":\"O=C(Cl)C(=O)Cl\",\"experiments_details\":\" To a stirred solution of 4-nitrophenyl acetic acid (1.00 g, 5.53 mmol) and dimethylformamide (catalytic, 3 drops) in dichloromethane (25 ml) was added oxalyl chloride (0.59 ml, 6.91 mmol) dropwise via syringe and the reaction stirred at room temperature for 30 minutes. Glycine tert-butyl ester (1.44 g, 11.06 mmol) was added in one portion and the reaction left to stir at room temperature for 1 hour. The reaction was washed with water, separated, the organic layer dried over sodium sulfate, filtered and concentrated onto silica in vacuo. The reaction was purified by column chromatography eluting with 1:1 EtOAc:Hexane as eluent to afford the named product (0.900 g). LCMS Rₜ=3.30 min, m/z (ES+) 295 (M+H). \",\"file_name\":\"US20110245250\"}]}"
 },
 {
  "type": "text",
  "text": "{\"query\":\"COC(=O)[C@@H](N)CO.Cl.O=C(O)Cc1ccc(-c2noc(C(F)(F)F)n2)cc1>>COC(=O)[C@H](CO)NC(=O)Cc1ccc(-c2noc(C(F)(F)F)n2)cc1\",\"results\":[{\"reactants\":\"N#Cc1ccc(N)cc1C(F)(F)F.O=C(O)Cc1ccc(Br)cc1\",\"products\":\"N#Cc1ccc(NC(=O)Cc2ccc(Br)cc2)cc1C(F)(F)F\",\"solvents\":\"ClC(Cl)Cl.ClCCl\",\"reagents\":\"O=C(Cl)C(=O)Cl.c1ccncc1\",\"experiments_details\":\" Dissolve 4-bromo-phenyl acetic acid (5 g, 23.3 mmol) in 125 mL dichloromethane. Add 1 mL DMF, stir to give a clear solution, then add oxalyl chloride (3.25 g, 2.23 mL, 25.5 mmol) portionwise via syringe and stir at room temperature for 15-30 minutes until gas evolution ceases. Remove volatiles on rotovap to yield a clear yellow oil. Dissolve the oil in 100 mL amylene-stabilized chloroform, chill on ice and fit flask with a dropping funnel. Fill the dropping funnel with a solution of 4-amino-2-trifluoromethyl-benzonitrile (4.65 g, 25 mmol) and pyridine (6.05 g, 6.19 mL, 76.5 mmol) in 200 mL amylene-stabilized chloroform. Add the benzonitrile solution to the cold acid chloride solution with stirring over 30 minutes, remove the ice bath and stir overnight at room temperature. Dilute the reaction mixture with 200 mL dichloromethane, wash twice with 250 mL portions of 1 N NaHSO₄, once with aqueous saturated sodium chloride, then dry over MgSO₄ and concentrate to a brown solid. Purify on Biotage 75L® silica cartridge in 4.5:4.5:1 CH₂Cl₂:hexanes:diethyl ether to yield 4.33 g (48%) of the title compound as a pale yellow-ivory solid. LCMS (ES) m/z 381,383 (M−1). \",\"file_name\":\"US20090227622\"}]}"
 },
 {
  "type": "text",
  "text": "{\"query\":\"COC(=O)[C@@H](N)CO.Cl.O=C(O)Cc1ccc(-c2noc(C(F)(F)F)n2)cc1>>COC(=O)[C@H](CO)NC(=O)Cc1ccc(-c2noc(C(F)(F)F)n2)cc1\",\"results\":[{\"reactants\":\"Cl.Cl.N[C@@H](Cc1ccccn1)C(=O)NCC(=O)OCc1ccccc1.O=C(O)C=Cc1ccc(Cl)cc1\",\"products\":\"O=C(/C=C/c1ccc(Cl)cc1)N[C@@H](Cc1ccccn1)C(=O)NCC(=O)OCc1ccccc1\",\"solvents\":\"ClCCl.ClCCl\",\"reagents\":\"CCN(CC)CC.O=C(Cl)C(=O)Cl\",\"experiments_details\":\"To a solution of 4-chlorocinnamic acid (49.2 g) in dichloromethane (400 ml) were added oxalyl chloride (30.5 ml) and 1 drop of N,N-dimethylformamide, and the mixture was stirred at room temperature for 6 hours. The reaction mixture was evaporated to dryness, and the residual acid chloride was dissolved in dichloromethane (900 ml). To this solution was added benzyl [[(2S)-2-amino-3-(2-pyridyl)propanoyl]amino]acetate dihydrochloride (104 g) at 10°C. followed by addition of triethylamine (116 ml) over 40 minutes. The mixture was allowed to warm to room temperature and stirred for 2 hours. The reaction mixture was evaporated to dryness, and the residue was washed successively with water (500 ml×5) and tetrahydrofuran-n-hexane (1:2, 500 ml×10), and dried in vacuo to give the title compound (115 g) as a white solid. \",\"file_name\":\"US6825200\"}]}"
 }
]

